#!/bin/sh
# Generate the overlays of the other sensors from cubie-a7s-imx327.dtso (the
# one validated on the board): same CSI1/MIPI1/TWI3 routing, PE8 (connector
# pin 11, power enable of Pi camera modules) and PE9, I2C address 0x1a; only
# the VIN sensor name (= driver module name) and the texts change.
#   sh overlays/gen-sensor-overlays.sh
set -e
cd "$(dirname "$0")"
src=cubie-a7s-imx327.dtso

gen() { # sensor module title
	out=cubie-a7s-$1.dtso
	{
		cat <<EOF
/*
 * Cubie A7S: $3 on the 31-pin CSI connector (15-to-31 cable).
 * GENERATED by gen-sensor-overlays.sh from cubie-a7s-imx327.dtso (validated
 * 2026-10-16): only the sensor name and these texts differ. Driver $2
 * (drivers/, DKMS). Not yet tested with this sensor.
 * Enable one sensor overlay at a time (they share CSI1 and TWI3).
 */
EOF
		# body of the IMX327 overlay, from the first non-comment line
		sed -n '/^\/dts-v1\/;/,$p' "$src" \
		| sed -e "s/sensor0_mname = \"imx327_mipi\";/sensor0_mname = \"$2\";/" \
		      -e "s/title = \"[^\"]*\";/title = \"Enable $3\";/" \
		      -e "s/description = \"[^\"]*\";/description = \"$3 on CSI1\\/MIPI1, driver $2 (2 lanes, RAW). Untested.\";/"
	} > "$out"
	grep -q "sensor0_mname = \"$2\";" "$out"
	echo "$out"
}

gen imx462 imx462_mipi "Sony IMX462 RAW (Pi-style module)"
gen imx477 imx477_mipi "Sony IMX477 RAW (Raspberry Pi HQ camera or compatible)"
gen imx585 imx585_mipi "Sony IMX585 RAW (StarlightEye or compatible)"
gen imx678 imx678_mipi "Sony IMX678 RAW (StarlightEye or compatible)"
gen imx662 imx662_mipi "Sony IMX662 RAW (StarlightEye or compatible)"
